import type { DashboardFilters } from "@/lib/filters/schema";
import { fmtDuration, fmtInt, fmtPct, statusLabel } from "@/lib/format";
import type { Spike } from "./anomalies";
import type { CrossTab, GroupMetrics, PeriodComparison, RecurringSessions } from "./types";
import { relativeChange } from "./stats";

/**
 * Deterministic management insights. Every statement is computed from the
 * supplied aggregates with explicit thresholds; nothing is generated by an
 * AI model and no cause is asserted. Each insight carries its evidence and a
 * link to the filtered view that reproduces it.
 */

export type InsightSeverity = "info" | "watch" | "attention";
export type InsightArea = "volume" | "trend" | "resolution" | "backlog" | "recurring" | "data";

export interface InsightLink {
  pathname: string;
  overrides?: Partial<DashboardFilters>;
  extra?: Record<string, string>;
  hash?: string;
  label: string;
}

export interface Insight {
  id: string;
  area: InsightArea;
  severity: InsightSeverity;
  title: string;
  statement: string;
  evidence: { label: string; value: string }[];
  link?: InsightLink;
}

export interface InsightInputs {
  overall: GroupMetrics | null;
  projects: GroupMetrics[];
  topics: GroupMetrics[];
  topicPeriods: PeriodComparison | null;
  topicThemes: CrossTab | null;
  recurring: RecurringSessions | null;
  lessons?: GroupMetrics[];
  spikes: Spike[];
  subcategoryLabels: Record<string, string>;
  thresholds: { response_seconds: number; resolution_seconds: number };
}

export const RULES = {
  /** Minimum tickets in the current period for a topic trend to be reported. */
  trendMinCurrent: 20,
  /** Minimum relative change for a topic to be called rising/falling. */
  trendMinChange: 0.5,
  /** Minimum resolved tickets for a topic's resolution time to be compared. */
  slowTopicMinN: 30,
  /** A topic is "slow" when its median exceeds the overall median by this factor. */
  slowTopicFactor: 1.25,
  /** A theme dominates a topic when it covers at least this share of it. */
  dominantThemeShare: 0.4,
  dominantThemeMinTopic: 100,
  /** A lesson is reported only when at least this many different students referenced it. */
  lessonMinStudents: 50,
} as const;

function share(part: number, whole: number): number | null {
  return whole > 0 ? part / whole : null;
}

export function buildInsights(input: InsightInputs): Insight[] {
  const out: Insight[] = [];
  const overall = input.overall;
  if (!overall || overall.tickets === 0) return out;

  // 1. Volume leader --------------------------------------------------------
  const projects = [...input.projects].sort((a, b) => b.tickets - a.tickets);
  if (projects.length > 1) {
    const top = projects[0];
    out.push({
      id: "volume-leader",
      area: "volume",
      severity: "info",
      title: `${top.label} has the highest ticket volume`,
      statement: `${top.label} accounts for ${fmtPct(share(top.tickets, overall.tickets))} of tickets in the current view (${fmtInt(top.tickets)} of ${fmtInt(overall.tickets)}).`,
      evidence: projects.map((p) => ({ label: p.label, value: `${fmtInt(p.tickets)} (${fmtPct(share(p.tickets, overall.tickets))})` })),
      link: { pathname: "/projects", label: "Compare projects" },
    });
  }

  // 2. Rising / falling topics ---------------------------------------------
  const periods = input.topicPeriods;
  if (periods?.current && periods.previous) {
    const rows = periods.rows
      .map((r) => ({ ...r, change: relativeChange(r.current, r.previous) }))
      .filter((r) => r.current >= RULES.trendMinCurrent && r.change !== null && Math.abs(r.change) >= RULES.trendMinChange);
    const periodText = `${periods.current.from} → ${periods.current.to} vs. ${periods.previous.from} → ${periods.previous.to}`;
    for (const r of rows.filter((x) => (x.change ?? 0) > 0).sort((a, b) => (b.change ?? 0) - (a.change ?? 0)).slice(0, 3)) {
      out.push({
        id: `topic-rising-${r.key}`,
        area: "trend",
        severity: "watch",
        title: `"${r.key}" is becoming more frequent`,
        statement: `${fmtInt(r.current)} tickets in the latest ${periods.current.days} days, up ${fmtPct(r.change, 0)} from ${fmtInt(r.previous)} in the preceding ${periods.previous.days} days. The data shows the increase, not its cause.`,
        evidence: [
          { label: "Current period", value: fmtInt(r.current) },
          { label: "Previous period", value: fmtInt(r.previous) },
          { label: "Periods compared", value: periodText },
        ],
        link: { pathname: "/topics", overrides: { topics: [r.key] }, label: "Open topic" },
      });
    }
    for (const r of rows.filter((x) => (x.change ?? 0) < 0).sort((a, b) => (a.change ?? 0) - (b.change ?? 0)).slice(0, 2)) {
      out.push({
        id: `topic-falling-${r.key}`,
        area: "trend",
        severity: "info",
        title: `"${r.key}" is less frequent than before`,
        statement: `${fmtInt(r.current)} tickets in the latest ${periods.current.days} days, down ${fmtPct(Math.abs(r.change ?? 0), 0)} from ${fmtInt(r.previous)}.`,
        evidence: [
          { label: "Current period", value: fmtInt(r.current) },
          { label: "Previous period", value: fmtInt(r.previous) },
          { label: "Periods compared", value: periodText },
        ],
        link: { pathname: "/trends", overrides: { topics: [r.key] }, label: "View trend" },
      });
    }
  }

  // 3. Topics with longer resolution ----------------------------------------
  const overallMedian = overall.resolution_median_s;
  if (overallMedian && overallMedian > 0) {
    const slow = input.topics
      .filter((t) => t.resolution_n >= RULES.slowTopicMinN && (t.resolution_median_s ?? 0) >= overallMedian * RULES.slowTopicFactor)
      .sort((a, b) => (b.resolution_median_s ?? 0) - (a.resolution_median_s ?? 0))
      .slice(0, 3);
    for (const t of slow) {
      out.push({
        id: `topic-slow-${t.key}`,
        area: "resolution",
        severity: "watch",
        title: `"${t.key}" takes longer to resolve`,
        statement: `Median resolution is ${fmtDuration(t.resolution_median_s)} versus ${fmtDuration(overallMedian)} across all tickets in view (${(((t.resolution_median_s ?? 0) / overallMedian)).toFixed(1)}×), based on ${fmtInt(t.resolution_n)} resolved tickets.`,
        evidence: [
          { label: "Median resolution", value: fmtDuration(t.resolution_median_s) },
          { label: "90th percentile", value: fmtDuration(t.resolution_p90_s) },
          { label: "Resolved tickets (n)", value: fmtInt(t.resolution_n) },
        ],
        link: { pathname: "/backlog", overrides: { topics: [t.key] }, label: "Resolution detail" },
      });
    }
  }

  // 4. Outstanding issues by project ----------------------------------------
  const withOpen = projects.filter((p) => p.open_tickets > 0).sort((a, b) => b.open_tickets - a.open_tickets);
  if (withOpen.length > 0) {
    const totalOpen = withOpen.reduce((a, p) => a + p.open_tickets, 0);
    const top = withOpen[0];
    out.push({
      id: "outstanding-projects",
      area: "backlog",
      severity: top.open_breaches > 0 ? "attention" : "watch",
      title: `${fmtInt(totalOpen)} tickets are still unresolved in the latest exports`,
      statement: `${top.label} has the most (${fmtInt(top.open_tickets)}, ${fmtPct(share(top.open_tickets, top.tickets), 2)} of its tickets). ${fmtInt(withOpen.reduce((a, p) => a + p.open_breaches, 0))} unresolved tickets were older than the resolution threshold at export time.`,
      evidence: withOpen.map((p) => ({ label: p.label, value: `${fmtInt(p.open_tickets)} open · ${fmtInt(p.open_breaches)} over threshold` })),
      link: { pathname: "/backlog", label: "Open backlog" },
    });
  }

  // 5. Dominant themes inside broad topics (recurring complaints) ------------
  if (input.topicThemes) {
    const byTopic = new Map<string, { total: number; cells: { col: string; count: number }[] }>();
    for (const c of input.topicThemes.cells) {
      const entry = byTopic.get(c.row) ?? { total: 0, cells: [] };
      entry.total += c.count;
      entry.cells.push({ col: c.col, count: c.count });
      byTopic.set(c.row, entry);
    }
    const found: Insight[] = [];
    for (const [topic, entry] of byTopic) {
      if (entry.total < RULES.dominantThemeMinTopic) continue;
      const best = entry.cells
        .filter((c) => !["no_free_text", "unmatched", "__none__"].includes(c.col))
        .sort((a, b) => b.count - a.count)[0];
      if (!best) continue;
      const s = share(best.count, entry.total) ?? 0;
      if (s < RULES.dominantThemeShare) continue;
      const theme = input.subcategoryLabels[best.col] ?? best.col;
      found.push({
        id: `theme-${topic}-${best.col}`,
        area: "recurring",
        severity: "watch",
        title: `Most "${topic}" tickets mention ${theme.toLowerCase()}`,
        statement: `${fmtPct(s, 0)} of "${topic}" tickets (${fmtInt(best.count)} of ${fmtInt(entry.total)}) match the "${theme}" keyword rules. This is a recurring complaint pattern worth operational investigation; keyword matching is indicative, not a verified root cause.`,
        evidence: [
          { label: "Matching tickets", value: fmtInt(best.count) },
          { label: "Tickets in topic", value: fmtInt(entry.total) },
          { label: "Method", value: "Rule-based keywords (Arabic + English), rules-v1" },
        ],
        link: { pathname: "/topics", overrides: { topics: [topic], subcategories: [best.col] }, label: "Inspect tickets" },
      });
    }
    out.push(...found.sort((a, b) => a.id.localeCompare(b.id)).slice(0, 3));
  }

  // 6. Sessions reported by several students --------------------------------
  const rec = input.recurring;
  if (rec && rec.summary.recurring_sessions > 0) {
    const top = rec.sessions[0];
    out.push({
      id: "recurring-sessions",
      area: "recurring",
      severity: "info",
      title: `${fmtInt(rec.summary.recurring_sessions)} sessions were reported by ${rec.summary.min_students}+ different students`,
      statement: `These sessions account for ${fmtInt(rec.summary.tickets_in_recurring_sessions)} tickets. The most reported is session ${top.session_ref}${top.lesson_name ? ` (${top.lesson_name})` : ""} with ${fmtInt(top.tickets)} tickets from ${fmtInt(top.students)} students.`,
      evidence: rec.sessions.slice(0, 5).map((s) => ({ label: `Session ${s.session_ref} · ${s.project_code}`, value: `${s.students} students, ${s.tickets} tickets` })),
      link: { pathname: "/topics", label: "See recurring sessions", hash: "recurring" },
    });
  }

  // 6b. Lessons referenced by many different students ---------------------
  const lessons = (input.lessons ?? []).filter((l) => l.key !== "__none__" && l.unique_owners >= RULES.lessonMinStudents);
  if (lessons.length > 0) {
    const top = [...lessons].sort((a, b) => b.unique_owners - a.unique_owners).slice(0, 5);
    out.push({
      id: "lesson-hotspots",
      area: "recurring",
      severity: "info",
      title: `Lesson "${top[0].key}" is referenced by the most students`,
      statement: `${fmtInt(top[0].unique_owners)} different students raised ${fmtInt(top[0].tickets)} tickets about sessions of this lesson. Lessons that recur across many students are candidates for a content or delivery review; the ticket topic shows what was reported.`,
      evidence: top.map((l) => ({ label: l.key, value: `${fmtInt(l.unique_owners)} students · ${fmtInt(l.tickets)} tickets` })),
      link: { pathname: "/tickets", overrides: { lesson: top[0].key }, label: "Read these tickets" },
    });
  }

  // 7. Unusual volume days ----------------------------------------------------
  if (input.spikes.length > 0) {
    const top = [...input.spikes].sort((a, b) => b.score - a.score).slice(0, 5);
    out.push({
      id: "volume-spikes",
      area: "trend",
      severity: "watch",
      title: `${input.spikes.length} day(s) with unusually high ticket volume`,
      statement: `Volume on these days exceeded the trailing 28-day median by a robust z-score of 3.5 or more. The data does not show why; check for platform incidents, deadlines or campaigns.`,
      evidence: top.map((s) => ({ label: s.date, value: `${fmtInt(s.count)} tickets (typical ≈ ${fmtInt(s.baseline)})` })),
      link: { pathname: "/trends", extra: { grain: "day" }, label: "Daily trend" },
    });
  }

  // 8. Threshold breaches -----------------------------------------------------
  const breachRate = share(overall.resolution_breaches, overall.resolution_n);
  if (breachRate !== null) {
    const worst = projects
      .filter((p) => p.resolution_n > 0)
      .map((p) => ({ p, rate: share(p.resolution_breaches, p.resolution_n) ?? 0 }))
      .sort((a, b) => b.rate - a.rate);
    out.push({
      id: "resolution-threshold",
      area: "resolution",
      severity: breachRate > 0.5 ? "attention" : breachRate > 0.2 ? "watch" : "info",
      title: `${fmtPct(breachRate, 0)} of resolved tickets exceeded the ${fmtDuration(input.thresholds.resolution_seconds)} resolution threshold`,
      statement: `The threshold is an illustrative monitoring value (configurable in Settings), not a contractual SLA.${worst[0] ? ` Highest breach rate: ${worst[0].p.label} (${fmtPct(worst[0].rate, 0)}).` : ""}`,
      evidence: worst.map(({ p, rate }) => ({ label: p.label, value: `${fmtPct(rate, 0)} of ${fmtInt(p.resolution_n)}` })),
      link: { pathname: "/backlog", label: "Threshold analysis" },
    });
  }

  // 9. Data caveat on response timestamps ------------------------------------
  const genericShare = share(overall.generic_ack, overall.tickets);
  if (genericShare !== null && genericShare > 0.5) {
    out.push({
      id: "response-caveat",
      area: "data",
      severity: "info",
      title: "Recorded response times are not proof of a human reply",
      statement: `${fmtPct(genericShare, 1)} of tickets carry a templated acknowledgement as their response text, and ${fmtInt(overall.tickets - overall.with_response_ts)} tickets have no response timestamp. Treat "recorded first response" metrics as system timestamps.`,
      evidence: [
        { label: "Generic acknowledgements", value: fmtInt(overall.generic_ack) },
        { label: "Response timestamp recorded", value: fmtPct(share(overall.with_response_ts, overall.tickets)) },
        { label: `Tickets with status "${statusLabel(null)}"`, value: fmtInt(overall.missing_status) },
      ],
      link: { pathname: "/data-quality", label: "Data quality" },
    });
  }

  const order: Record<InsightSeverity, number> = { attention: 0, watch: 1, info: 2 };
  return out.sort((a, b) => order[a.severity] - order[b.severity]);
}
